final class Tree: Sendable {}

func close() async {
    print("closed")
}

func process(_ items: [String]) async -> Int {
    print("opening")
    defer { await close() }
    for item in items {
        print(item)
    }
    return items.count
}

final class Leaf: Sendable {
    weak let tree: Tree?

    init(tree: Tree?) {
        self.tree = tree
    }
}

